# Independent authenticated fixed-IP endpoint prerequisite. Fresh hosted VM only.
[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$ReportPath)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$WarningPreference='SilentlyContinue'
function Assert-NativeOrdinaryPath([string]$Path){$current=[IO.Path]::GetFullPath($Path);while($current){if(Test-Path -LiteralPath $current){if((Get-Item -LiteralPath $current -Force -ErrorAction Stop).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Ordinary path required'}};$next=Split-Path -Parent $current;if($next -eq $current){break};$current=$next}}
$project=Split-Path -Parent $PSScriptRoot
$sources=@('scripts/doh-ip-authority-control.cjs','scripts/test-doh-ip-authority-control.cjs','scripts/doh-ip-authority-evidence.ps1','scripts/test-doh-ip-authority-source.ps1','scripts/test-doh-ip-authority.ps1','scripts/ndis-tls-control.cjs','scripts/native-dns-wire.ps1','.github/workflows/native-doh-ip-authority.yml')
$hashes=@{};foreach($file in $sources){$hashes[$file]=(Get-FileHash -LiteralPath (Join-Path $project $file) -Algorithm SHA256).Hash.ToLowerInvariant()}
$rows=[Collections.Generic.List[object]]::new();$state=$null;$environmentVerified=$false;$nativeProcessVerified=$false;$outcome='failed';$code='environment';$coverage=0
try{
    if($env:GITHUB_ACTIONS -cne 'true' -or $env:RUNNER_ENVIRONMENT -cne 'github-hosted' -or $env:RUNNER_OS -cne 'Windows' -or $env:GITHUB_SHA -cnotmatch '^[a-f0-9]{40}$' -or $env:ACCESSWEAVER_EXPECT_GOOS -cne 'windows' -or $env:ACCESSWEAVER_EXPECT_GOARCH -cnotin @('amd64','arm64') -or $PSVersionTable.PSEdition -cne 'Desktop' -or $PSVersionTable.PSVersion.Major -ne 5 -or $PSVersionTable.PSVersion.Minor -ne 1 -or [IntPtr]::Size -ne 8){throw 'Hosted Windows identity required'}
    foreach($name in @('ACCESSWEAVER_HISTORY_INTEROP','ACCESSWEAVER_RECONCILIATION_INTEROP','ACCESSWEAVER_CONTROLLER_STORAGE_INTEROP','ACCESSWEAVER_SUPPORT_INTEROP')){if($null -ne [Environment]::GetEnvironmentVariable($name,'Process')){throw 'Interop boundary refused'}}
    $computer=Get-CimInstance Win32_ComputerSystem -ErrorAction Stop;if($computer.Model -notmatch 'Virtual|VMware' -or $computer.PartOfDomain -ne $false){throw 'Fresh non-domain VM required'}
    $machineRoot=Join-Path $env:ProgramData 'AccessWeaver';Assert-NativeOrdinaryPath $machineRoot;if((Test-Path -LiteralPath $machineRoot) -or @(Get-Service -Name 'AccessWeaver*' -ErrorAction SilentlyContinue).Count -ne 0){throw 'Preexisting product state refused'}
    Add-Type -TypeDefinition 'using System;using System.Diagnostics;using System.Runtime.InteropServices;public static class AccessWeaverIPAuthorityIdentity{[DllImport("kernel32.dll",SetLastError=true)]private static extern bool IsWow64Process2(IntPtr process,out ushort processMachine,out ushort nativeMachine);public static bool Matches(string architecture){using(Process process=Process.GetCurrentProcess()){ushort machine,native;if(!IsWow64Process2(process.Handle,out machine,out native))return false;return machine==0&&native==(architecture=="amd64"?0x8664:0xaa64);}}}'
    if(-not [AccessWeaverIPAuthorityIdentity]::Matches($env:ACCESSWEAVER_EXPECT_GOARCH)){throw 'Native process architecture required'};$nativeProcessVerified=$true;$environmentVerified=$true
    $code='private-root';$root=[IO.Path]::Combine([Environment]::GetFolderPath('LocalApplicationData'),('AccessWeaver-IPAuthority-'+[guid]::NewGuid().ToString('N')));Assert-NativeOrdinaryPath $root;if(Test-Path -LiteralPath $root){throw 'Existing private root'};[void][IO.Directory]::CreateDirectory($root)
    $identity=[Security.Principal.WindowsIdentity]::GetCurrent();$acl=[Security.AccessControl.DirectorySecurity]::new();$acl.SetOwner($identity.User);$acl.SetAccessRuleProtection($true,$false);foreach($sid in @($identity.User.Value,'S-1-5-18','S-1-5-32-544') | Select-Object -Unique){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new($sid),'FullControl','ContainerInherit,ObjectInherit','None','Allow'))};Set-Acl -LiteralPath $root -AclObject $acl -ErrorAction Stop
    . (Join-Path $PSScriptRoot 'native-dns-wire.ps1');. (Join-Path $PSScriptRoot 'doh-ip-authority-evidence.ps1');$state=New-NativeDNSWireState $root (Join-Path $PSScriptRoot 'dns-wire-stdin.cjs')
    $code='node';$version=Invoke-NativeDNSWireProcess $state $state.node @('--version');if($version.Trim() -cne 'v26.8.2'){throw 'Pinned Node required'}
    $code='endpoint'
    foreach($ordinal in @(0,1)){
        foreach($file in $sources){if((Get-FileHash -LiteralPath (Join-Path $project $file) -Algorithm SHA256).Hash.ToLowerInvariant() -cne $hashes[$file]){throw 'Source changed'}}
        try{$text=Invoke-NativeDNSWireProcess $state $state.node @((Join-Path $PSScriptRoot 'doh-ip-authority-control.cjs'),([string]$ordinal));$v=Get-DoHIPAuthorityEndpoint $text ($ordinal+1)}catch{$v=New-DoHIPAuthorityEndpoint ($ordinal+1) 'tool'}
        $rows.Add($v);$coverage=$coverage -bor $v.certificateMask
    }
    $code=if(@($rows | Where-Object {$_.outcome -cne 'passed'}).Count -ne 0){'endpoint'}else{'coverage'};if((Test-DoHIPAuthorityCoverage @($rows.ToArray())) -and -not $state.processFailed -and $state.processes -eq 3 -and $state.joined -eq 3){$outcome='passed';$code='none'}
    foreach($file in $sources){if((Get-FileHash -LiteralPath (Join-Path $project $file) -Algorithm SHA256).Hash.ToLowerInvariant() -cne $hashes[$file]){$outcome='failed';$code='source-changed'}}
}catch{$outcome='failed'}
finally{
    $ReportPath=[IO.Path]::GetFullPath($ReportPath);Assert-NativeOrdinaryPath $ReportPath;$parent=Get-Item -LiteralPath ([IO.Path]::GetDirectoryName($ReportPath)) -Force -ErrorAction Stop
    if([IO.Path]::GetFileName($ReportPath) -cne 'status.json' -or $parent.Name -cnotmatch '^accessweaver-ip-authority-[a-f0-9]{32}$' -or -not $parent.Parent.FullName.Equals([IO.Path]::GetFullPath($env:RUNNER_TEMP).TrimEnd('\'),[StringComparison]::OrdinalIgnoreCase) -or [IO.Directory]::GetFileSystemEntries($parent.FullName).Length -ne 0){throw 'Fixed report boundary'}
    $processes=0;$joined=0;$toolFailure=$false;if($null -ne $state){$processes=$state.processes;$joined=$state.joined;$toolFailure=$state.processFailed}
    $r=@{schemaVersion=1;scope='hosted-authenticated-ip-authority-prerequisite';sourceCommit=$env:GITHUB_SHA;sourceSHA256=$hashes;platform='windows';architecture=$env:ACCESSWEAVER_EXPECT_GOARCH;edition=$PSVersionTable.PSEdition;version=$PSVersionTable.PSVersion.ToString();outcome=$outcome;code=$code;environmentVerified=$environmentVerified;nativeProcessVerified=$nativeProcessVerified;requestedEndpointMask=3;certificateIPCoverageMask=$coverage;ipv6TransportTested=$false;endpoints=@($rows.ToArray());processes=$processes;joined=$joined;toolFailure=$toolFailure;productInvoked=$false;dnsSettingsChangesAttempted=$false;firewallRulesCreated=$false;nativeCapturePerformed=$false;credentialStoresQueried=$false;rawCertificatesPublished=$false;rawLogsRead=$false;productionQualificationComplete=$false}
    $bytes=[Text.UTF8Encoding]::new($false).GetBytes(($r | ConvertTo-Json -Depth 6 -Compress));if($bytes.Length -gt 16384){throw 'Fixed report bound'};$stream=[IO.FileStream]::new($ReportPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()}
}
if($outcome -cne 'passed'){exit 1}
